      ..add(data);
    final size = n + 11;
    _b.add([
      size >> 24 & 0xFF,
      size >> 16 & 0xFF,
      size >> 8 & 0xFF,
      size & 0xFF,
    ]);
  }

  void avcHeader(List<int> avcC) => tag(9, 0, [0x17, 0, 0, 0, 0, ...avcC]);

  void video(int ts, List<int> payload, {bool key = false, int cts = 0}) =>
