Future<void> setDataSource(
  DataSource dataSource, {
  bool isLive = false,
  bool autoplay = true,
  // 初始化播放位置
  Duration? seekTo,
  // 初始化播放速度
  double speed = 1.0,
  int? width,
  int? height,
  Duration? duration,
  // 方向
  bool? isVertical,
  // 记录历史记录
  int? aid,
  String? bvid,
  int? cid,
  int? epid,
  int? seasonId,
  int? pgcType,
  VideoType? videoType,
  VoidCallback? onInit,
  Volume? volume,
  bool autoFullScreenFlag = false,
}) async {
  try {
    _processing = true;
    this.isLive = isLive;
    _videoType = videoType ?? VideoType.ugc;
    this.width = width;
    this.height = height;
    this.dataSource = dataSource;
    _autoPlay = autoplay;
    // 初始化视频倍速
    // _playbackSpeed.value = speed;
    // 初始化数据加载状态
    dataStatus.value = DataStatus.loading;
    // 初始化全屏方向
    _isVertical = isVertical ?? false;
    _aid = aid;
    _bvid = bvid;
    this.cid = cid;
    _epid = epid;
    _seasonId = seasonId;
    _pgcType = pgcType;

    if (showSeekPreview) {
      _clearPreview();
    }
    cancelLongPressTimer();
    if (_videoPlayerController != null &&
        _videoPlayerController!.state.playing) {
      await pause(notify: false);
    }

    if (_playerCount == 0) {
      return;
    }
    // 配置Player 音轨、字幕等等
    await _createVideoController(dataSource, seekTo, volume);

    if (_playerCount == 0) {
      _removeListeners();
      _videoPlayerController?.dispose();
      _videoPlayerController = null;
      _videoController = null;
      return;
    }

