41	class LocalFolderMatch {
42	  const LocalFolderMatch({
43	    required this.video,
44	    required this.sideFiles,
45	    this.imagesDir,
46	  });
47	
48	  final LocalDocument video;
49	
50	  /// Small files read next to the video (download record, cover, danmaku,
51	  /// subtitles, comments).
