8	/// Losslessly merges single-track fragmented MP4 inputs (bilibili DASH
9	/// `video.m4s` / `audio.m4s`) into one progressive MP4 with `moov` placed
10	/// before `mdat` (fast start).
11	///
12	/// Sample data is copied byte-for-byte, codec configuration (`stsd`) and edit
13	/// lists are carried over, so any codec the inputs carry (AVC / HEVC / AV1 /
14	/// AAC ...) is supported. Pure Dart, no Flutter dependency: safe to run inside
15	/// `Isolate.run`.
16	abstract final class Mp4Remuxer {
17	  static const _movieTimescale = 1000;
18	  static const _maxChunkSeconds = 1.0;
19	  static const _copyBufferSize = 4 << 20;
20	
21	  static Future<void> remux({
22	    required List<String> inputs,
23	    required String output,
24	    void Function(int copied, int total)? onProgress,
25	  }) async {
26	    if (inputs.isEmpty) throw ArgumentError('no input');
27	    final tracks = <_Track>[];
28	    for (final input in inputs) {
29	      tracks.add(
30	        await _Track.parse(input)
31	          ..index = tracks.length,
32	      );
33	    }
34	    await _write(tracks, output, onProgress);
35	  }
36	
37	  /// Whether [path] starts with an FLV header.
38	  static bool isFlv(String path) => _hasMagic(path, 0, 'FLV');
39	
40	  /// Whether [path] is an (ISO BMFF) MP4 file.
41	  static bool isMp4(String path) => _hasMagic(path, 4, 'ftyp');
42	
43	  static bool _hasMagic(String path, int offset, String magic) {
44	    final raf = File(path).openSync();
45	    try {
46	      raf.setPositionSync(offset);
47	      return String.fromCharCodes(raf.readSync(magic.length)) == magic;
48	    } finally {
49	      raf.closeSync();
50	    }
51	  }
52	
53	  /// Joins FLV segments (in timeline order) into one progressive MP4.
54	  /// Supports H.264 video and AAC audio; anything else throws
55	  /// [UnsupportedError] so the caller can keep the original file.
56	  static Future<void> remuxFlv({
57	    required List<String> inputs,
58	    required String output,
59	    void Function(int copied, int total)? onProgress,
60	  }) async {
61	    if (inputs.isEmpty) throw ArgumentError('no input');
62	    await _write(_FlvDemuxer.demux(inputs), output, onProgress);
63	  }
64	
65	  /// Joins progressive MP4 segments (in timeline order) into one MP4.
66	  /// Throws [UnsupportedError] when the segments' tracks or codec
67	  /// configurations differ, so the caller can keep them separate.
68	  static Future<void> joinMp4({
69	    required List<String> inputs,
70	    required String output,
71	    void Function(int copied, int total)? onProgress,
72	  }) async {
73	    if (inputs.isEmpty) throw ArgumentError('no input');
74	    await _write(_Mp4Joiner.join(inputs), output, onProgress);
75	  }
76	
77	  /// The tracks an FLV demux produces; for tests only.
78	  static List<Map<String, Object>> debugFlvTracks(List<String> inputs) =>
79	      _debugSummary(_FlvDemuxer.demux(inputs));
80	
81	  /// The tracks [joinMp4] reads from progressive MP4 inputs; for tests only.
82	  static List<Map<String, Object>> debugMp4JoinTracks(List<String> inputs) =>
83	      _debugSummary(_Mp4Joiner.join(inputs));
84	
85	  static List<Map<String, Object>> _debugSummary(List<_Track> tracks) => [
86	    for (final t in tracks)
87	      {
88	        'type': t.sampleEntryType,
89	        'timescale': t.timescale,
90	        'sizes': t.sizes,
91	        'durations': t.durations,
92	        'ctos': t.ctos,
93	        'syncs': t.syncs,
94	        'stsd': t.stsd,
95	        'tkhdTail': t.tkhdTail,
96	        'edits': [
97	          for (final e in t.edits) [e.segmentDuration, e.mediaTime],
98	        ],
99	      },
100	  ];
101	
102	  static Future<void> _write(
103	    List<_Track> tracks,
104	    String output,
105	    void Function(int copied, int total)? onProgress,
106	  ) async {
107	    final chunks = [for (final t in tracks) ...t.chunks]
108	      ..sort((a, b) {
109	        final c = a.startSeconds.compareTo(b.startSeconds);
110	        return c != 0 ? c : a.track.index.compareTo(b.track.index);
111	      });
112	
113	    final payloadSize = chunks.fold<int>(0, (s, c) => s + c.length);
114	    final ftyp = _ftyp(tracks);
115	    // Size of moov does not depend on offset values, only on stco vs co64.
116	    final useCo64 = payloadSize + ftyp.length + (64 << 20) > 0xFFFFFFFF;
117	    final mdatHeaderSize = payloadSize + 8 > 0xFFFFFFFF ? 16 : 8;
118	    final moovSize = _moov(tracks, useCo64).length;
119	    var offset = ftyp.length + moovSize + mdatHeaderSize;
120	    for (final c in chunks) {
121	      c.outputOffset = offset;
122	      offset += c.length;
123	    }
124	    final moov = _moov(tracks, useCo64);
125	    assert(moov.length == moovSize);
126	
127	    final tmp = File('$output.part');
128	    final out = await tmp.open(mode: FileMode.write);
129	    final sources = <String, RandomAccessFile>{};
130	    try {
131	      await out.writeFrom(ftyp);
132	      await out.writeFrom(moov);
133	      final mdatHeader = _W();
134	      if (mdatHeaderSize == 16) {
135	        mdatHeader
136	          ..u32(1)
137	          ..fourcc('mdat')
138	          ..u64(payloadSize + 16);
139	      } else {
140	        mdatHeader
141	          ..u32(payloadSize + 8)
142	          ..fourcc('mdat');
143	      }
144	      await out.writeFrom(mdatHeader.bytes);
145	
146	      final buffer = Uint8List(_copyBufferSize);
147	      var copied = 0;
148	      for (final c in chunks) {
149	        final src = sources[c.sourcePath] ??= await File(
150	          c.sourcePath,
151	        ).open();
152	        await src.setPosition(c.sourceOffset);
153	        var remaining = c.length;
154	        while (remaining > 0) {
155	          final n = await src.readInto(
156	            buffer,
157	            0,
158	            remaining < buffer.length ? remaining : buffer.length,
159	          );
160	          if (n <= 0) {
161	            throw FormatException('unexpected EOF in ${c.sourcePath}');
162	          }
163	          await out.writeFrom(buffer, 0, n);
164	          remaining -= n;
165	          copied += n;
166	        }
167	        onProgress?.call(copied, payloadSize);
168	      }
169	    } catch (_) {
170	      await out.close();
171	      for (final s in sources.values) {
172	        await s.close();
173	      }
174	      if (tmp.existsSync()) await tmp.delete();
175	      rethrow;
176	    }
177	    await out.close();
178	    for (final s in sources.values) {
179	      await s.close();
180	    }
181	    final dest = File(output);
182	    if (dest.existsSync()) await dest.delete();
183	    await tmp.rename(output);
184	  }
185	
186	  static Uint8List _ftyp(List<_Track> tracks) {
187	    final brands = <String>{'isom', 'iso2', 'mp41'};
188	    for (final t in tracks) {
189	      final fmt = t.sampleEntryType;
190	      if (fmt == 'avc1' || fmt == 'avc3') brands.add('avc1');
191	      if (fmt == 'av01') brands.add('av01');
192	    }
193	    final w = _W()
194	      ..fourcc('isom')
195	      ..u32(0x200);
196	    brands.forEach(w.fourcc);
197	    return _box('ftyp', w.bytes);
198	  }
199	
200	  static Uint8List _moov(List<_Track> tracks, bool useCo64) {
201	    final traks = <Uint8List>[];
202	    var movieDuration = 0;
203	    for (var i = 0; i < tracks.length; i++) {
204	      final t = tracks[i];
205	      final trackDuration = t.movieDuration;
206	      movieDuration = max(movieDuration, trackDuration);
207	      traks.add(t.buildTrak(i + 1, trackDuration, useCo64));
208	    }
209	    final mvhd = _W();
210	    final v1 = movieDuration > 0xFFFFFFFF;
211	    mvhd.u32(v1 ? 0x01000000 : 0);
212	    if (v1) {
213	      mvhd
214	        ..u64(0)
215	        ..u64(0)
216	        ..u32(_movieTimescale)
217	        ..u64(movieDuration);
218	    } else {
219	      mvhd
220	        ..u32(0)
221	        ..u32(0)
222	        ..u32(_movieTimescale)
223	        ..u32(movieDuration);
224	    }
225	    mvhd
226	      ..u32(0x00010000) // rate
227	      ..u16(0x0100) // volume
228	      ..zeros(10)
229	      ..bytes_(_unityMatrix)
230	      ..zeros(24)
231	      ..u32(tracks.length + 1);
232	    return _box('moov', _concat([_box('mvhd', mvhd.bytes), ...traks]));
233	  }
234	}
235	
236	final _unityMatrix = () {
237	  final w = _W();
238	  for (final v in [0x00010000, 0, 0, 0, 0x00010000, 0, 0, 0, 0x40000000]) {
239	    w.u32(v);
240	  }
241	  return w.bytes;
242	}();
