244	class _Chunk {
245	  _Chunk(
246	    this.track,
247	    this.sourceOffset,
248	    this.firstSample,
249	    this.startDts, [
250	    String? sourcePath,
251	  ]) : sourcePath = sourcePath ?? track.path;
252	  final _Track track;
253	
254	  /// File the chunk's bytes are read from (FLV input: one per segment).
255	  final String sourcePath;
256	  final int sourceOffset;
257	  final int firstSample;
258	  final int startDts;
259	  int length = 0;
260	  int sampleCount = 0;
261	  int outputOffset = 0;
262	  double get startSeconds => startDts / track.timescale;
263	}
