265	class _EditEntry {
266	  _EditEntry(this.segmentDuration, this.mediaTime, this.rate);
267	  int segmentDuration; // in source movie timescale; 0 = until end
268	  final int mediaTime; // in media timescale; -1 = empty edit
269	  final int rate;
270	}
