272	class _Track {
273	  _Track(this.path);
274	  final String path;
275	  int index = 0;
276	
277	  late int timescale;
278	  late int sourceMovieTimescale;
279	  late String sampleEntryType;
280	  late Uint8List tkhdTail; // layer .. height, copied verbatim
281	  late int tkhdFlags;
282	  late Uint8List mdhdLanguage;
283	  late Uint8List hdlr;
284	  late Uint8List mediaHeader; // vmhd / smhd / nmhd
285	  late Uint8List dinf;
286	  late Uint8List stsd;
287	  final edits = <_EditEntry>[];
288	
289	  // trex defaults
290	  int _trexDuration = 0;
291	  int _trexSize = 0;
292	  int _trexFlags = 0;
293	
294	  final durations = <int>[];
295	  final sizes = <int>[];
296	  final ctos = <int>[];
297	  final syncs = <bool>[];
298	  final chunks = <_Chunk>[];
299	
300	  int get mediaDuration => durations.fold(0, (s, d) => s + d);
301	
302	  /// End of the last presented sample in media time (decode time plus
303	  /// composition offset); exceeds [mediaDuration] when B-frames reorder.
304	  int get presentationEnd {
305	    var dts = 0;
306	    var end = 0;
307	    for (var i = 0; i < durations.length; i++) {
308	      end = max(end, dts + ctos[i] + durations[i]);
309	      dts += durations[i];
310	    }
311	    return end;
312	  }
313	
314	  int get movieDuration {
315	    if (edits.isEmpty) {
316	      return _scale(mediaDuration, timescale, Mp4Remuxer._movieTimescale);
317	    }
318	    var total = 0;
319	    for (final e in _resolvedEdits()) {
320	      total += e.segmentDuration;
321	    }
322	    return total;
323	  }
324	
325	  /// Edits converted to the output movie timescale, with "until end" (0)
326	  /// segment durations of fragmented files resolved against the real length.
327	  List<_EditEntry> _resolvedEdits() {
328	    return [
329	      for (final e in edits)
330	        _EditEntry(
331	          e.segmentDuration == 0 && e.mediaTime >= 0
332	              ? _scale(
333	                  max(0, presentationEnd - e.mediaTime),
334	                  timescale,
335	                  Mp4Remuxer._movieTimescale,
336	                )
337	              : _scale(
338	                  e.segmentDuration,
339	                  sourceMovieTimescale,
340	                  Mp4Remuxer._movieTimescale,
341	                ),
342	          e.mediaTime,
343	          e.rate,
344	        ),
345	    ];
346	  }
347	
348	  static Future<_Track> parse(String path) async {
349	    final t = _Track(path);
350	    final raf = await File(path).open();
351	    try {
352	      final length = await raf.length();
353	      var pos = 0;
354	      var sawMoov = false;
355	      var dts = 0;
356	      while (pos + 8 <= length) {
357	        await raf.setPosition(pos);
358	        final header = await raf.read(16);
359	        final hd = ByteData.sublistView(header);
360	        var size = hd.getUint32(0);
361	        final type = String.fromCharCodes(header, 4, 8);
362	        var headerSize = 8;
363	        if (size == 1) {
364	          size = hd.getUint64(8);
365	          headerSize = 16;
366	        } else if (size == 0) {
367	          size = length - pos;
368	        }
369	        if (size < headerSize || pos + size > length) {
370	          throw FormatException('bad box $type at $pos in $path');
371	        }
372	        if (type == 'moov') {
373	          await raf.setPosition(pos + headerSize);
374	          t._parseMoov(await raf.read(size - headerSize));
375	          sawMoov = true;
376	        } else if (type == 'moof') {
377	          if (!sawMoov) throw FormatException('moof before moov in $path');
378	          await raf.setPosition(pos + headerSize);
379	          dts = t._parseMoof(await raf.read(size - headerSize), pos, dts);
380	        }
381	        pos += size;
382	      }
383	      if (!sawMoov) throw FormatException('no moov in $path');
384	      if (t.sizes.isEmpty) throw FormatException('no samples in $path');
385	      return t;
386	    } finally {
387	      await raf.close();
388	    }
389	  }
390	
391	  void _parseMoov(Uint8List moov) {
392	    final r = _R(moov);
393	    sourceMovieTimescale = Mp4Remuxer._movieTimescale;
394	    var trakCount = 0;
395	    for (final (type, body) in r.boxes()) {
396	      switch (type) {
397	        case 'mvhd':
398	          final b = _R(body);
399	          final v = b.u8();
400	          b.skip(3 + (v == 1 ? 16 : 8));
401	          sourceMovieTimescale = b.u32();
402	        case 'mvex':
403	          for (final (t2, b2) in _R(body).boxes()) {
404	            if (t2 == 'trex') {
405	              final b = _R(b2)..skip(12);
406	              _trexDuration = b.u32();
407	              _trexSize = b.u32();
408	              _trexFlags = b.u32();
409	            }
410	          }
411	        case 'trak':
412	          trakCount++;
413	          _parseTrak(body);
414	      }
415	    }
416	    if (trakCount != 1) {
417	      throw FormatException('expected 1 track, got $trakCount in $path');
418	    }
419	  }
420	
421	  void _parseTrak(Uint8List trak) {
422	    for (final (type, body) in _R(trak).boxes()) {
423	      switch (type) {
424	        case 'tkhd':
425	          final b = _R(body);
426	          final v = b.u8();
427	          tkhdFlags = b.u24();
428	          // skip times, track id, reserved, duration
429	          b.skip(v == 1 ? 32 : 20);
430	          tkhdTail = b.rest();
431	        case 'edts':
432	          for (final (t2, b2) in _R(body).boxes()) {
433	            if (t2 != 'elst') continue;
434	            final b = _R(b2);
435	            final v = b.u8();
436	            b.skip(3);
437	            final n = b.u32();
438	            for (var i = 0; i < n; i++) {
439	              final seg = v == 1 ? b.u64() : b.u32();
440	              final mt = v == 1 ? b.i64() : b.i32();
441	              edits.add(_EditEntry(seg, mt, b.u32()));
442	            }
443	          }
444	        case 'mdia':
445	          _parseMdia(body);
446	      }
447	    }
448	  }
449	
450	  void _parseMdia(Uint8List mdia) {
451	    for (final (type, body) in _R(mdia).boxes()) {
452	      switch (type) {
453	        case 'mdhd':
454	          final b = _R(body);
455	          final v = b.u8();
456	          b.skip(3 + (v == 1 ? 16 : 8));
457	          timescale = b.u32();
458	          b.skip(v == 1 ? 8 : 4);
459	          mdhdLanguage = b.bytes(2);
460	        case 'hdlr':
461	          hdlr = _box('hdlr', body);
462	        case 'minf':
463	          for (final (t2, b2) in _R(body).boxes()) {
464	            switch (t2) {
465	              case 'vmhd' || 'smhd' || 'nmhd' || 'sthd':
466	                mediaHeader = _box(t2, b2);
467	              case 'dinf':
468	                dinf = _box(t2, b2);
469	              case 'stbl':
470	                for (final (t3, b3) in _R(b2).boxes()) {
471	                  if (t3 == 'stsd') {
472	                    stsd = _box(t3, b3);
473	                    sampleEntryType = String.fromCharCodes(b3, 12, 16);
474	                  }
475	                }
476	            }
477	          }
478	      }
479	    }
480	  }
481	
482	  /// Returns the decode time after this fragment.
483	  int _parseMoof(Uint8List moof, int moofOffset, int dts) {
484	    for (final (type, body) in _R(moof).boxes()) {
485	      if (type != 'traf') continue;
486	      var baseOffset = moofOffset;
487	      var defDuration = _trexDuration;
488	      var defSize = _trexSize;
489	      var defFlags = _trexFlags;
490	      int? nextDataOffset;
491	      for (final (t2, b2) in _R(body).boxes()) {
492	        final b = _R(b2);
493	        switch (t2) {
494	          case 'tfhd':
495	            final flags = b.u32() & 0xFFFFFF;
496	            b.skip(4); // track id
497	            if (flags & 0x1 != 0) baseOffset = b.u64();
498	            if (flags & 0x2 != 0) b.skip(4);
499	            if (flags & 0x8 != 0) defDuration = b.u32();
500	            if (flags & 0x10 != 0) defSize = b.u32();
501	            if (flags & 0x20 != 0) defFlags = b.u32();
502	          case 'tfdt':
503	            final v = b.u8();
504	            b.skip(3);
505	            dts = v == 1 ? b.u64() : b.u32();
506	          case 'trun':
507	            final vf = b.u32();
508	            final version = vf >>> 24;
509	            final flags = vf & 0xFFFFFF;
510	            final n = b.u32();
511	            var dataOffset = nextDataOffset ?? baseOffset;
512	            if (flags & 0x1 != 0) dataOffset = baseOffset + b.i32();
513	            int? firstFlags;
514	            if (flags & 0x4 != 0) firstFlags = b.u32();
515	            _Chunk? chunk;
516	            var chunkDuration = 0;
517	            final maxChunk = (Mp4Remuxer._maxChunkSeconds * timescale).round();
518	            for (var i = 0; i < n; i++) {
519	              final dur = flags & 0x100 != 0 ? b.u32() : defDuration;
520	              final size = flags & 0x200 != 0 ? b.u32() : defSize;
521	              final sFlags = flags & 0x400 != 0
522	                  ? b.u32()
523	                  : (i == 0 && firstFlags != null ? firstFlags : defFlags);
524	              final cto = flags & 0x800 != 0
525	                  ? (version == 0 ? b.u32() : b.i32())
526	                  : 0;
527	              if (chunk == null || chunkDuration >= maxChunk) {
528	                chunk = _Chunk(this, dataOffset, sizes.length, dts);
529	                chunks.add(chunk);
530	                chunkDuration = 0;
531	              }
532	              durations.add(dur);
533	              sizes.add(size);
534	              ctos.add(cto);
535	              // sample_is_non_sync_sample
536	              syncs.add(sFlags & 0x10000 == 0);
537	              chunk
538	                ..length += size
539	                ..sampleCount += 1;
540	              chunkDuration += dur;
541	              dataOffset += size;
542	              dts += dur;
543	            }
544	            nextDataOffset = dataOffset;
545	        }
546	      }
547	    }
548	    return dts;
549	  }
550	
551	  Uint8List buildTrak(int trackId, int trackDuration, bool useCo64) {
552	    final tkhd = _W();
553	    final v1 = trackDuration > 0xFFFFFFFF;
554	    tkhd.u32((v1 ? 0x01000000 : 0) | tkhdFlags | 0x3);
555	    if (v1) {
556	      tkhd
557	        ..u64(0)
558	        ..u64(0)
559	        ..u32(trackId)
560	        ..u32(0)
561	        ..u64(trackDuration);
562	    } else {
563	      tkhd
564	        ..u32(0)
565	        ..u32(0)
566	        ..u32(trackId)
567	        ..u32(0)
568	        ..u32(trackDuration);
569	    }
570	    tkhd.bytes_(tkhdTail);
571	
572	    final parts = <Uint8List>[_box('tkhd', tkhd.bytes)];
573	
574	    if (edits.isNotEmpty) {
575	      final resolved = _resolvedEdits();
576	      final needV1 = resolved.any(
577	        (e) =>
578	            e.segmentDuration > 0xFFFFFFFF ||
579	            e.mediaTime > 0x7FFFFFFF ||
580	            e.mediaTime < -0x80000000,
581	      );
582	      final elst = _W()
583	        ..u32(needV1 ? 0x01000000 : 0)
584	        ..u32(resolved.length);
585	      for (final e in resolved) {
586	        if (needV1) {
587	          elst
588	            ..u64(e.segmentDuration)
589	            ..i64(e.mediaTime);
590	        } else {
591	          elst
592	            ..u32(e.segmentDuration)
593	            ..u32(e.mediaTime);
594	        }
595	        elst.u32(e.rate);
596	      }
597	      parts.add(_box('edts', _box('elst', elst.bytes)));
598	    }
599	
600	    final mdhd = _W();
601	    final dur = mediaDuration;
602	    final mv1 = dur > 0xFFFFFFFF;
603	    mdhd.u32(mv1 ? 0x01000000 : 0);
604	    if (mv1) {
605	      mdhd
606	        ..u64(0)
607	        ..u64(0)
608	        ..u32(timescale)
609	        ..u64(dur);
610	    } else {
611	      mdhd
612	        ..u32(0)
613	        ..u32(0)
614	        ..u32(timescale)
615	        ..u32(dur);
616	    }
617	    mdhd
618	      ..bytes_(mdhdLanguage)
619	      ..u16(0);
620	
621	    final stbl = _box(
622	      'stbl',
623	      _concat([
624	        stsd,
625	        _stts(),
626	        ?_ctts(),
627	        ?_stss(),
628	        _stsz(),
629	        _stsc(),
630	        _stco(useCo64),
631	      ]),
632	    );
633	    final minf = _box('minf', _concat([mediaHeader, dinf, stbl]));
634	    final mdia = _box('mdia', _concat([_box('mdhd', mdhd.bytes), hdlr, minf]));
635	    parts.add(mdia);
636	    return _box('trak', _concat(parts));
637	  }
638	
639	  Uint8List _stts() {
640	    final entries = <(int, int)>[];
641	    for (final d in durations) {
642	      if (entries.isNotEmpty && entries.last.$2 == d) {
643	        entries.last = (entries.last.$1 + 1, d);
644	      } else {
645	        entries.add((1, d));
646	      }
647	    }
648	    final w = _W()
649	      ..u32(0)
650	      ..u32(entries.length);
651	    for (final (count, delta) in entries) {
652	      w
653	        ..u32(count)
654	        ..u32(delta);
655	    }
656	    return _box('stts', w.bytes);
657	  }
658	
659	  Uint8List? _ctts() {
660	    if (ctos.every((e) => e == 0)) return null;
661	    final signed = ctos.any((e) => e < 0);
662	    final entries = <(int, int)>[];
663	    for (final c in ctos) {
664	      if (entries.isNotEmpty && entries.last.$2 == c) {
665	        entries.last = (entries.last.$1 + 1, c);
666	      } else {
667	        entries.add((1, c));
668	      }
669	    }
670	    final w = _W()
671	      ..u32(signed ? 0x01000000 : 0)
672	      ..u32(entries.length);
673	    for (final (count, offset) in entries) {
674	      w
675	        ..u32(count)
676	        ..u32(offset);
677	    }
678	    return _box('ctts', w.bytes);
679	  }
680	
681	  Uint8List? _stss() {
682	    if (syncs.every((e) => e)) return null;
683	    final w = _W()..u32(0);
684	    final idx = <int>[
685	      for (var i = 0; i < syncs.length; i++)
686	        if (syncs[i]) i + 1,
687	    ];
688	    w.u32(idx.length);
689	    idx.forEach(w.u32);
690	    return _box('stss', w.bytes);
691	  }
692	
693	  Uint8List _stsz() {
694	    final w = _W()..u32(0);
695	    final first = sizes.first;
696	    if (sizes.every((e) => e == first)) {
697	      w
698	        ..u32(first)
699	        ..u32(sizes.length);
700	    } else {
701	      w
702	        ..u32(0)
703	        ..u32(sizes.length);
704	      sizes.forEach(w.u32);
705	    }
706	    return _box('stsz', w.bytes);
707	  }
708	
709	  Uint8List _stsc() {
710	    final entries = <(int, int)>[];
711	    for (var i = 0; i < chunks.length; i++) {
712	      final n = chunks[i].sampleCount;
713	      if (entries.isEmpty || entries.last.$2 != n) entries.add((i + 1, n));
714	    }
715	    final w = _W()
716	      ..u32(0)
717	      ..u32(entries.length);
718	    for (final (firstChunk, perChunk) in entries) {
719	      w
720	        ..u32(firstChunk)
721	        ..u32(perChunk)
722	        ..u32(1);
723	    }
724	    return _box('stsc', w.bytes);
725	  }
726	
727	  Uint8List _stco(bool co64) {
728	    final w = _W()
729	      ..u32(0)
730	      ..u32(chunks.length);
731	    for (final c in chunks) {
732	      co64 ? w.u64(c.outputOffset) : w.u32(c.outputOffset);
733	    }
734	    return _box(co64 ? 'co64' : 'stco', w.bytes);
735	  }
736	}
737	
738	int _scale(int value, int from, int to) =>
739	    from == to ? value : (value * to + from ~/ 2) ~/ from;
740	
741	Uint8List _box(String type, Uint8List body) {
742	  final size = body.length + 8;
743	  final w = _W();
744	  if (size > 0xFFFFFFFF) {
745	    w
746	      ..u32(1)
747	      ..fourcc(type)
748	      ..u64(size + 8);
749	  } else {
750	    w
751	      ..u32(size)
752	      ..fourcc(type);
753	  }
754	  return _concat([w.bytes, body]);
755	}
756	
757	Uint8List _concat(List<Uint8List> parts) {
758	  final b = BytesBuilder(copy: false);
759	  parts.forEach(b.add);
760	  return b.takeBytes();
761	}
762	
763	class _W {
764	  final _b = BytesBuilder();
765	  final _tmp = ByteData(8);
766	  Uint8List get bytes => _b.toBytes();
767	
768	  void u8(int v) => _b.addByte(v & 0xFF);
769	
770	  void u16(int v) {
771	    _tmp.setUint16(0, v);
772	    _b.add(_tmp.buffer.asUint8List(0, 2));
773	  }
774	
775	  void u32(int v) {
776	    _tmp.setUint32(0, v & 0xFFFFFFFF);
777	    _b.add(_tmp.buffer.asUint8List(0, 4));
778	  }
779	
780	  void u64(int v) {
781	    _tmp.setUint64(0, v);
782	    _b.add(_tmp.buffer.asUint8List(0, 8));
783	  }
784	
785	  void i64(int v) {
786	    _tmp.setInt64(0, v);
787	    _b.add(_tmp.buffer.asUint8List(0, 8));
788	  }
789	
790	  void fourcc(String s) => _b.add(s.codeUnits);
791	  void zeros(int n) => _b.add(Uint8List(n));
792	  void bytes_(Uint8List data) => _b.add(data);
793	}
794	
795	class _R {
796	  _R(this.data) : _bd = ByteData.sublistView(data);
797	  final Uint8List data;
798	  final ByteData _bd;
799	  int pos = 0;
800	
801	  int u8() => _bd.getUint8(pos++);
802	  int u24() {
803	    final v = (_bd.getUint8(pos) << 16) | _bd.getUint16(pos + 1);
804	    pos += 3;
805	    return v;
806	  }
807	
808	  int u32() {
809	    final v = _bd.getUint32(pos);
810	    pos += 4;
811	    return v;
812	  }
813	
814	  int i32() {
815	    final v = _bd.getInt32(pos);
816	    pos += 4;
817	    return v;
818	  }
819	
820	  int u64() {
821	    final v = _bd.getUint64(pos);
822	    pos += 8;
823	    return v;
824	  }
825	
826	  int i64() {
827	    final v = _bd.getInt64(pos);
828	    pos += 8;
829	    return v;
830	  }
831	
832	  void skip(int n) => pos += n;
833	  Uint8List bytes(int n) {
834	    final v = Uint8List.sublistView(data, pos, pos + n);
835	    pos += n;
836	    return v;
837	  }
838	
839	  Uint8List rest() => Uint8List.sublistView(data, pos);
840	
841	  /// Iterates child boxes of the current buffer, yielding (type, body).
842	  Iterable<(String, Uint8List)> boxes() sync* {
843	    var p = 0;
844	    while (p + 8 <= data.length) {
845	      var size = _bd.getUint32(p);
846	      final type = String.fromCharCodes(data, p + 4, p + 8);
847	      var header = 8;
848	      if (size == 1) {
849	        size = _bd.getUint64(p + 8);
850	        header = 16;
851	      } else if (size == 0) {
852	        size = data.length - p;
853	      }
854	      if (size < header || p + size > data.length) {
855	        throw FormatException('bad box $type');
856	      }
857	      yield (type, Uint8List.sublistView(data, p + header, p + size));
858	      p += size;
859	    }
860	  }
861	}
