      } else if (type == 'trak') {
        traks.add(body);
      }
    }
    final tracks = <_Track>[];
    for (final trak in traks) {
      final t = _Track(path)
        ..sourceMovieTimescale = movieTimescale
        .._parseTrak(trak);
