    }
    if (tracks.isEmpty) throw FormatException('no samples in $path');
    return tracks;
  }

  static Map<String, Uint8List> _stbl(Uint8List trak) {
    for (final (type, mdia) in _R(trak).boxes()) {
      if (type != 'mdia') continue;
      for (final (t2, minf) in _R(mdia).boxes()) {
