        final count = b.u32();
        final delta = b.u32();
        for (var j = 0; j < count && durations.length < n; j++) {
          durations.add(delta);
        }
      }
    }
    while (durations.length < n) {
      durations.add(durations.isEmpty ? 0 : durations.last);
    }

    // composition offsets
    final ctos = <int>[];
    if (stbl['ctts'] case final body?) {
      final b = _R(body);
      final signed = b.u8() == 1;
      b.skip(3);
      final entries = b.u32();
      for (var i = 0; i < entries && ctos.length < n; i++) {
