    if (sample < n) {
      throw FormatException('chunk tables cover $sample of $n samples');
    }
    t
      ..sizes.addAll(sizes)
      ..durations.addAll(durations)
      ..ctos.addAll(ctos)
      ..syncs.addAll(syncs);
  }
}

