7	/// Writes bits MSB first, with Exp-Golomb helpers (for building an SPS).
8	class _Bits {
9	  final _out = <int>[];
10	  int _cur = 0;
11	  int _n = 0;
12	
13	  void bit(int b) {
14	    _cur = (_cur << 1) | (b & 1);
15	    if (++_n == 8) {
16	      _out.add(_cur);
17	      _cur = 0;
18	      _n = 0;
19	    }
20	  }
21	
22	  void bits(int v, int n) {
23	    for (var i = n - 1; i >= 0; i--) {
24	      bit((v >> i) & 1);
25	    }
26	  }
27	
28	  void ue(int v) {
29	    final x = v + 1;
30	    final len = x.bitLength;
31	    bits(0, len - 1);
32	    bits(x, len);
33	  }
34	
35	  List<int> rbsp() {
36	    bit(1); // rbsp_stop_one_bit
37	    while (_n != 0) {
38	      bit(0);
39	    }
40	    return _out;
41	  }
42	}
43	
44	/// Baseline SPS for [widthMbs] x [heightMbs] macroblocks, optional bottom
45	/// crop (in crop units).
46	List<int> _sps(int widthMbs, int heightMbs, {int cropBottom = 0}) {
47	  final b = _Bits()
48	    ..bits(66, 8) // profile_idc baseline
49	    ..bits(0, 8) // constraint flags
50	    ..bits(30, 8) // level
51	    ..ue(0) // sps id
52	    ..ue(0) // log2_max_frame_num_minus4
53	    ..ue(2) // pic_order_cnt_type
54	    ..ue(1) // max_num_ref_frames
55	    ..bit(0) // gaps
56	    ..ue(widthMbs - 1)
57	    ..ue(heightMbs - 1)
58	    ..bit(1) // frame_mbs_only
59	    ..bit(1); // direct_8x8_inference
60	  if (cropBottom > 0) {
61	    b
62	      ..bit(1)
63	      ..ue(0)
64	      ..ue(0)
65	      ..ue(0)
66	      ..ue(cropBottom);
67	  } else {
68	    b.bit(0);
69	  }
70	  b.bit(0); // vui
71	  return [0x67, ...b.rbsp()];
72	}
