74	List<int> _avcC(List<int> sps) => [
75	  1, sps[1], sps[2], sps[3], 0xFF, 0xE1, //
76	  sps.length >> 8, sps.length & 0xFF, ...sps,
77	  1, 0, 4, 0x68, 0xCE, 0x38, 0x80, // one PPS
78	];
