+/// A document reached through the Storage Access Framework (Android).
+class LocalDocument {
+  const LocalDocument({
+    required this.name,
+    required this.uri,
+    this.size = 0,
+    this.isDir = false,
+    this.docId,
+    this.key,
+  });
+
+  final String name;
+
+  /// `content://` URI, readable through the grant the user gave.
+  final String uri;
+  final int size;
+  final bool isDir;
