+    name: map['name'] as String? ?? '',
+    uri: map['uri'] as String,
+    size: (map['size'] as num?)?.toInt() ?? 0,
+    isDir: map['isDir'] as bool? ?? false,
+    docId: map['docId'] as String?,
+    key: map['key'] as String?,
