  final separate = chroma == 3 && b.bit() == 1;
  var width = b.ue();
  var height = b.ue();
  if (b.bit() == 1) {
    final left = b.ue();
    final right = b.ue();
    final top = b.ue();
    final bottom = b.ue();
    final subW = !separate && (chroma == 1 || chroma == 2) ? 2 : 1;
    final subH = !separate && chroma == 1 ? 2 : 1;
