/** Keeps read access across restarts (resume / reopen), within the system limit. */
private fun keepGrant(uri: Uri) {
    try {
        val kept = contentResolver.persistedUriPermissions
        if (kept.size >= MAX_KEPT_GRANTS) {
            kept.sortedBy { it.persistedTime }
                .take(kept.size - MAX_KEPT_GRANTS + 1)
                .forEach {
                    contentResolver.releasePersistableUriPermission(
                        it.uri,
                        Intent.FLAG_GRANT_READ_URI_PERMISSION,
                    )
                }
        }
        contentResolver.takePersistableUriPermission(
            uri,
            Intent.FLAG_GRANT_READ_URI_PERMISSION,
        )
    } catch (_: SecurityException) {
        // not persistable: still readable for this session
    }
}

