      final inband = [0, 0, 0, _spsHevc320.length, ..._spsHevc320];
      expect(v['sizes'], [15, 15, 15 + inband.length, 15]);
      final mp4 = File(output).readAsBytesSync();
      final at = _indexOf(mp4, [...inband, ..._nal(10, 2)]);
      expect(at, isNot(-1));
